#pragma once
// Self-contained device page: no CDN, npm server, Web Serial or mesh assets.
inline constexpr const char* kLampTwinPage = R"lamppage(<!doctype html>
<html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>台灯 · ESP32 测试面板</title>
<style>
:root{color-scheme:dark;font:15px system-ui,sans-serif;background:#111821;color:#e7eff8}*{box-sizing:border-box}body{margin:0}header{padding:18px 24px;border-bottom:1px solid #334052}h1{font-size:20px;margin:0 0 6px}small,.muted{color:#a1b0c2}main{max-width:1200px;margin:auto;padding:18px;display:grid;grid-template-columns:minmax(0,1.1fr) minmax(320px,1fr);gap:16px}section,details{background:#1a2431;border:1px solid #334052;border-radius:12px;padding:16px;margin-bottom:14px}summary{cursor:pointer;font-weight:650}button,input,select{font:inherit}button{border:1px solid #465974;border-radius:7px;background:#26384d;color:#e7eff8;padding:9px 12px;cursor:pointer}button.primary{background:#286add}button.danger{background:#8b3038}button:disabled{opacity:.4;cursor:default}input[type=number]{background:#101923;color:#e7eff8;border:1px solid #465974;border-radius:6px;width:92px;padding:6px}input[type=range]{width:100%;accent-color:#73a9ff}select{padding:7px;background:#101923;color:#fff;border:1px solid #465974;border-radius:6px}.buttons{display:flex;gap:8px;flex-wrap:wrap;margin:12px 0}.joint{padding:14px 0;border-bottom:1px solid #334052}.row{display:flex;align-items:center;justify-content:space-between;gap:12px}label{display:block}p{line-height:1.6}#message{white-space:pre-wrap;overflow-wrap:anywhere;min-height:42px;color:#b8d6ff}svg{display:block;width:100%;height:auto;aspect-ratio:620/430;background:#121c28;border-radius:8px}.cal-row{margin:14px 0;padding:12px;background:#121c28;border-radius:8px}.cal-row .row{flex-wrap:wrap;justify-content:flex-start}.cal-row input{width:100px}.cal-row label{font-size:13px;color:#b5c6db}.tag{padding:5px 9px;background:#27364a;border-radius:6px}pre{overflow:auto;font:12px monospace;max-height:320px}#feedback{font-size:13px;line-height:1.8}.notice{color:#ffce8b}@media(max-width:760px){main{display:block;padding:10px}header{padding:14px}.preview{position:static}}
</style>
<header><h1>台灯 · ESP32 测试面板</h1><small>五轴直连 · ESP32 串口驱动 · 安装偏置与方向校准</small></header>
<main><div><section class="preview"><div class="row"><b>2D 侧视图</b><span class="tag">J2 / J3 / J4</span></div>
<p class="muted">蓝色：目标预览　绿色：实际反馈<br>关节中心连线含安装偏移；J3＝0 不代表两段连线垂直。省略 Yaw 与末端旋转，不表示碰撞检测结果。</p>
<svg id="view" viewBox="0 0 620 430" preserveAspectRatio="xMidYMid meet" aria-label="台灯侧视连杆示意图"><path d="M20 398H600" stroke="#465974"/><rect x="260" y="386" width="100" height="12" rx="5" fill="#6a7c93"/><g id="target"/><g id="actual"/></svg>
<div class="buttons"><span id="yaw" class="tag">Yaw —</span><span id="roll" class="tag">末端旋转 —</span></div></section>
<details><summary>五轴反馈与诊断</summary><div id="feedback">等待反馈…</div><button id="export">导出本页日志</button><pre id="raw"></pre></details><details open><summary>对话与工具调用历史</summary><p class="muted">记录本次开机的语音文字、台灯 MCP 调用和任务结果。设备保留最近 64 KiB／128 条，长结果会注明截断；浏览器保留最近 500 条。重启清空设备记录。</p><button id="export-history">导出对话记录</button><p>特别关注：用户转写 → 工具调用 → 预备/释放 → 机械结果；疑似只说未动为诊断线索，不自动当作事实。</p><pre id="attention"></pre><pre id="history"></pre></details></div>
<div><section><b id="status">正在连接设备…</b><p id="message" role="status">页面打开不会使能或运动。</p>
<div class="buttons"><button id="acquire">进入手动测试</button><button id="release">退出手动测试</button></div>
<div class="buttons"><button id="enable">保持当前位置并使能</button><button id="stop" class="danger">停止</button><button id="off" class="danger">卸力 · 先扶住灯臂</button></div><small>手动测试期间暂停 MCP 动作；退出不自动卸力。使能前先确认安装映射。</small></section>
<details open><summary>五轴关节测试</summary><p class="muted">拖动滑条只预览；点击执行才运动。J2、J3 界面按抬头为正显示。</p><div id="joints"></div>
<div class="buttons"><button id="sync">采用当前反馈</button><label>运动时间（s） <input id="duration" type="number" min="0.2" max="10" step="0.1" value="1"></label></div>
<button id="move" class="primary">执行目标姿态</button></details>
<details><summary>安装零位与方向校准</summary><p class="notice">先进入手动测试，扶住灯臂并卸力。把单个关节放到已知参考角度，再记录；0° 是 URDF 零位，并非默认坐姿。</p>
<p class="muted">方向 ±1 相对于 URDF；可用下方两步判方向，或手动选择。参考角度使用上方界面的正方向约定。保存会清除旧“看人／看书”目标标定，并关闭运动授权。</p>
<div id="calibration"></div><div class="buttons"><button id="preview">检查候选映射</button><button id="save" class="primary">保存安装映射</button><button id="reload">恢复设备配置</button></div><pre id="mapping-preview"></pre></details></div></main>
<script>
const token='__TOKEN__',D=180/Math.PI,names=['底座 Yaw','底座俯仰','臂部俯仰','灯头俯仰','末端旋转'];
let historyEvents=[],historyCursor=0,historyLatest=0;
let directionStart=[],config,state,target=null,logs=[],requestCounter=0,busy=0,online=false;
const $=id=>document.getElementById(id),fmt=x=>Number.isFinite(x)?x.toFixed(1):'—';
function actualPose(){return config?.mapping.map(m=>state?.pose_rad?.[m.joint])}
function log(kind,data){logs.push({at:new Date().toISOString(),kind,data});if(logs.length>300)logs.shift()}
function tell(text){$('message').textContent=text}
async function api(path,body){const r=await fetch('/api/lamp/'+path,{method:body?'POST':'GET',headers:{'X-Lamp-Token':token,...(body?{'Content-Type':'application/json'}:{})},...(body?{body:JSON.stringify(body)}:{})});const data=await r.json();if(!r.ok||data.ok===false)throw Error(data.error?.message||'设备请求失败');return data}
async function command(operation,args={}){const request_id='web-'+Date.now().toString(36)+'-'+(++requestCounter);busy++;controls();log('request',{request_id,operation,args});try{const r=await api('command',{request_id,operation,args});if(r.ownership_changed){tell(operation==='acquire'?'已进入手动测试；请先检查反馈。':'已退出手动测试；力矩保持原状态。');return}tell('任务已受理，正在等待实际反馈…');for(let i=0;i<120;i++){await new Promise(r=>setTimeout(r,300));const t=await api('tasks/'+r.result.task_id);if(['completed','failed','cancelled','limited'].includes(t.result.status)){log('result',t.result);if(t.result.status!=='completed')throw Error(t.result.reason);tell(t.result.reason);return}}throw Error('本页等待超时，请查任务状态；不要重复使能或运动')}finally{busy--;await refresh();controls()}}
function safe(fn){return async()=>{try{await fn()}catch(e){log('error',String(e));tell(String(e))}}}
function controls(){const manual=online&&state?.manual_control,working=busy>0||state?.busy;for(const id of ['enable','move'])$(id).disabled=!manual||working||!state?.configuration_loaded;for(const id of ['preview','save'])$(id).disabled=!manual||working||!state?.unloaded_confirmed;$('acquire').disabled=!online||manual||working;$('release').disabled=!manual||working;$('stop').disabled=!online;$('off').disabled=!online;$('sync').disabled=!online||!state?.available;document.querySelectorAll('[data-capture],[data-direction-start],[data-direction-end]').forEach(b=>b.disabled=!manual||working||!state?.unloaded_confirmed||!state?.available)}
function setJoint(i,value){if(!Number.isFinite(value))return;const m=config.mapping[i];const lo=Math.min(m.lower_rad*m.display_sign,m.upper_rad*m.display_sign)*D,hi=Math.max(m.lower_rad*m.display_sign,m.upper_rad*m.display_sign)*D;value=Math.max(lo,Math.min(hi,value));target[i]=value/D*m.display_sign;$('q'+i).value=value.toFixed(1);$('s'+i).value=value;draw()}
function inputs(){const rows=config.mapping;$('joints').innerHTML=rows.map((m,i)=>{const lo=Math.min(m.lower_rad*m.display_sign,m.upper_rad*m.display_sign)*D,hi=Math.max(m.lower_rad*m.display_sign,m.upper_rad*m.display_sign)*D;return `<div class="joint"><div class="row"><label>${i+1} · ${names[i]}</label><span><input id="q${i}" type="number" min="${lo}" max="${hi}" step="0.1"> °</span></div><input id="s${i}" type="range" min="${lo}" max="${hi}" step="0.1"><small>${fmt(lo)}° ～ ${fmt(hi)}° · 反馈 <span id="a${i}">—</span></small><div class="buttons"><button id="minus${i}">−3° 预览</button><button id="plus${i}">+3° 预览</button></div></div>`}).join('');
$('calibration').innerHTML=rows.map((m,i)=>`<div class="cal-row"><b>${i+1} · ${names[i]}</b><div class="row"><label>方向<br><select id="d${i}"><option value="1">+1</option><option value="-1">−1</option></select></label><label>零位 tick<br><input id="z${i}" type="number" min="-1000" max="2000" step="0.01" value="${m.zero_ticks}"></label><label>参考角度 °<br><input id="r${i}" type="number" step="0.1" value="0"></label></div><div class="buttons"><button data-direction-start="${i}">① 记录方向起点</button><button data-direction-end="${i}">② 正向手掰后判方向</button><button data-capture="${i}">从当前反馈记录偏置</button></div></div>`).join('');
rows.forEach((m,i)=>{$('d'+i).value=m.direction;$('q'+i).onchange=e=>setJoint(i,+e.target.value);$('s'+i).oninput=e=>setJoint(i,+e.target.value);$('minus'+i).onclick=()=>setJoint(i,target[i]*D*m.display_sign-3);$('plus'+i).onclick=()=>setJoint(i,target[i]*D*m.display_sign+3)});
document.querySelectorAll('[data-direction-start]').forEach(b=>b.onclick=safe(async()=>{const i=+b.dataset.directionStart;if(!state?.unloaded_confirmed||!state?.servos[i]?.position_fresh)throw Error('需要卸力且反馈新鲜');directionStart[i]=state.servos[i].position_ticks;tell('已记录方向起点；沿界面角度增大的方向手掰少量，再点②。')}));
document.querySelectorAll('[data-direction-end]').forEach(b=>b.onclick=safe(async()=>{const i=+b.dataset.directionEnd;if(!state?.unloaded_confirmed||!state?.servos[i]?.position_fresh||!Number.isFinite(directionStart[i]))throw Error('先卸力并记录方向起点');const delta=state.servos[i].position_ticks-directionStart[i];if(Math.abs(delta)<3)throw Error('位移太小，请沿界面正方向多掰一点');$('d'+i).value=Math.sign(delta)*rows[i].display_sign;directionStart[i]=undefined;tell('已更新候选方向，尚未保存；请再记录参考角度偏置。')}));
document.querySelectorAll('[data-capture]').forEach(b=>b.onclick=safe(async()=>{const i=+b.dataset.capture,s=state?.servos[i],ref=+$('r'+i).value;if(!state?.unloaded_confirmed||!s?.position_fresh||!Number.isFinite(ref))throw Error('需要已卸力的新鲜位置反馈');const m=rows[i],raw=ref/m.display_sign;$('z'+i).value=(s.position_ticks-(+$('d'+i).value)*raw/.24).toFixed(4);tell('已更新候选偏置，尚未保存。请检查后保存。')}));
if(target)target.forEach((q,i)=>setJoint(i,q*D*rows[i].display_sign));controls()}
function mapping(){return config.mapping.map((m,i)=>({direction:+$('d'+i).value,zero_ticks:+$('z'+i).value}))}
async function load(){config=await api('config');if(!target)target=config.mapping.map(m=>Math.max(m.lower_rad,Math.min(m.upper_rad,0)));inputs()}
function points(q){if(!q||q.some(x=>!Number.isFinite(x)))return null;let y=0,z=.07261821,theta=0;const p=[[0,0],[y,z]];for(const [angle,dy,dz] of [[q[1],.0016404,.1149883],[q[2],.12030224,.03255759],[q[3],.03934471+.053718,-.00064533-.00084]]){theta+=angle;y+=Math.cos(theta)*dy-Math.sin(theta)*dz;z+=Math.sin(theta)*dy+Math.cos(theta)*dz;p.push([y,z])}return p.map(([y,z])=>[310+y*850,398-z*850])}
function sketch(id,q,color){const p=points(q);$(id).replaceChildren();if(!p)return;const ns='http://www.w3.org/2000/svg',add=(tag,attrs)=>{const el=document.createElementNS(ns,tag);for(const[k,v]of Object.entries(attrs))el.setAttribute(k,v);$(id).appendChild(el)};add('polyline',{points:p.map(v=>v.join(',')).join(' '),fill:'none',stroke:color,'stroke-width':8,'stroke-linecap':'round','stroke-linejoin':'round',opacity:.8});p.forEach(([cx,cy])=>add('circle',{cx,cy,r:6,fill:color}));const [cx,cy]=p.at(-1);add('circle',{cx,cy,r:16,fill:'none',stroke:color,'stroke-width':4})}
function draw(){sketch('target',target,'#74aaff');sketch('actual',state?.available?actualPose():null,'#5ce0ba');$('yaw').textContent='Yaw '+fmt(state?.pose_rad?.baseYaw*D)+'°';$('roll').textContent='末端旋转 '+fmt(state?.pose_rad?.headRoll*D)+'°'}
async function refresh(){try{state=await api('state');online=true;$('status').textContent=(state.manual_control?'手动测试中':'MCP 控制')+' · '+(state.motion_enabled?'已授权运动':'未授权运动')+' · '+(state.available?'五轴反馈正常':'反馈不完整');if(!target&&state.available)target=actualPose();if(config)config.mapping.forEach((m,i)=>{$('a'+i).textContent=state.servos[i]?.position_fresh?fmt(state.pose_rad?.[m.joint]*D*m.display_sign)+'°':'—'});$('feedback').replaceChildren();for(const s of state.servos){const p=document.createElement('p');p.textContent=`ID ${s.id} · tick ${s.position_ticks??'—'} · ${s.temperature_c??'—'}°C · ${s.voltage_mv===undefined?'—':(s.voltage_mv/1000).toFixed(2)}V · 扭矩 ${s.torque??'—'} · 模式 ${s.mode??'—'} · ${s.position_fresh?'位置新鲜':'位置过期'}${s.last_error?' · '+s.last_error:''}`;$('feedback').appendChild(p)}$('raw').textContent=JSON.stringify(state,null,2);draw()}catch(e){online=false;$('status').textContent='设备连接中断';$('actual').replaceChildren();log('network',String(e))}controls()}
$('acquire').onclick=safe(()=>command('acquire'));$('release').onclick=safe(()=>command('release'));$('enable').onclick=safe(()=>command('set_torque',{enabled:true}));$('stop').onclick=safe(()=>command('cancel'));$('off').onclick=safe(()=>command('set_torque',{enabled:false}));
$('sync').onclick=safe(async()=>{await refresh();if(!state?.available)throw Error('反馈不完整');target=actualPose();target.forEach((q,i)=>setJoint(i,q*D*config.mapping[i].display_sign));tell('已采用当前反馈作为目标；没有发送运动。')});
$('move').onclick=safe(()=>command('move',{pose_rad:Object.fromEntries(config.mapping.map((m,i)=>[m.joint,target[i]])),duration_sec:+$('duration').value}));
$('preview').onclick=safe(async()=>{const result=await api('calibration/preview',{mapping:mapping()});$('mapping-preview').textContent=JSON.stringify(result.mapping,null,2);tell('候选映射有效，尚未保存或运动。')});
$('save').onclick=safe(async()=>{if(!confirm('保存安装映射将清除旧的人脸／书本目标标定，并关闭运动授权。继续？'))return;await command('install',{mapping:mapping(),clear_targets:true});await load();await refresh();$('sync').click()});
$('reload').onclick=safe(async()=>{await load();tell('已恢复设备映射；没有改变力矩。')});
$('export').onclick=()=>{const blob=new Blob([JSON.stringify({config,state,logs},null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='lamp-twin-diagnostic.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};
function historyText(){return historyEvents.map(e=>`[开机 ${ (e.uptime_ms/1000).toFixed(2)}s] ${e.kind} ${e.name}\n${e.data}${e.truncated?"\n[内容截断]":""}`).join("\n\n")}
async function refreshHistory(){try{const r=await api("history?after="+historyCursor);if(r.latest<historyLatest){historyCursor=0;historyEvents=[];historyLatest=r.latest;return}historyLatest=r.latest;if(r.gap)historyEvents.push({uptime_ms:0,kind:"notice",name:"记录缺口",data:"较早记录已被设备环形缓冲覆盖"});historyCursor=r.cursor;historyEvents.push(...r.events);historyEvents=historyEvents.slice(-500);$("history").textContent=historyText();$("attention").textContent=historyEvents.filter(e=>e.kind==="attention").slice(-20).map(e=>`[${(e.uptime_ms/1000).toFixed(2)}s] ${e.name} ${e.data}`).join("\n")}catch(e){$("history").textContent="历史读取失败："+String(e)}}
$("export-history").onclick=()=>{const a=document.createElement("a");a.href=URL.createObjectURL(new Blob([historyText()],{type:"text/plain;charset=utf-8"}));a.download="lamp-conversation.txt";a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};
setInterval(refreshHistory,1000);
(async()=>{try{await load();await refresh();if(state?.available){target=actualPose();target.forEach((q,i)=>setJoint(i,q*D*config.mapping[i].display_sign))}}catch(e){tell(String(e))}while(true){await new Promise(r=>setTimeout(r,500));await refresh()}})();
</script></html>)lamppage";
